<template><view :class="['app-page',{dark}]"><ui-header :title="meta.title" back/><view v-if="type==='coupons'" class="coupon-tabs"><button :class="{active:couponMode==='owned'}" @tap="couponMode='owned';load()">我的优惠券</button><button :class="{active:couponMode==='public'}" @tap="couponMode='public';load()">领券中心</button></view><view v-if="items.length" class="content"><template v-if="type==='favorites'"><navigator v-for="item in items" :key="item.id" class="product-row" :url="'/pages/product/detail?id='+item.id" hover-class="tap-active"><image :src="item.image" mode="aspectFill"/><view><text class="row-title">{{item.name}}</text><text class="muted">{{item.subtitle}}</text><text class="price">¥{{Number(item.price).toFixed(2)}}</text></view><ui-icon name="chevron-right" :size="28"/></navigator></template><template v-else-if="type==='following'"><view v-for="item in items" :key="item.id" class="shop-row"><ui-shop-card :name="item.name" :fans="item.fans" action="取消关注" @action="unfollow(item)"/></view></template><template v-else-if="type==='coupons'"><view v-for="item in items" :key="item.id" class="coupon-card"><view class="coupon-icon"><ui-icon name="coupon" :size="52"/></view><view class="coupon-value"><text class="coupon-money">¥{{Number(item.amount).toFixed(0)}}</text><text>满{{Number(item.minSpend).toFixed(0)}}元可用</text></view><view class="coupon-copy"><text class="row-title">{{item.name}}</text><text class="muted">有效期至 {{displayDateTime(item.validUntil)}}</text><text class="muted">{{couponMode==='public'?(Number(item.claimed)>0?'已领取':'公开领取'):({unused:'未使用',used:'已使用',expired:'已过期',active:'可使用'}[item.status]||'不可使用')}}</text><text class="muted">{{item.productId?'指定商品可用':'平台商品通用'}}</text><button class="claim-button" v-if="couponMode==='public'" :disabled="claiming||Number(item.claimed)>0||Number(item.available)<1" @tap="claim(item)">领取</button></view></view></template><template v-else><navigator v-for="item in items" :key="item.id" class="poster-row" :url="'/pages/product/poster?id='+item.productId"><image :src="item.image" mode="aspectFill"/><view><text class="row-title">{{item.productName}}</text><text class="muted">{{displayDateTime(item.createdAt)}}</text></view></navigator></template></view><ui-page-status v-else :loading="loading" :title="meta.empty" :description="error" @retry="load"/></view></template>
<script>import{api}from'@/services/api';import{isDark}from'@/utils/app';export default{data(){return{couponMode:'owned',claiming:false,dark:false,type:'favorites',items:[],loading:true,error:'',meta:{title:'列表',empty:'暂无数据'}}},onLoad(q){this.dark=isDark();this.type=q.type||'favorites';this.load()},methods:{async claim(item){if(this.claiming)return;this.claiming=true;try{await api.claimCoupon(item.id);uni.showToast({title:'领取成功'});await this.load()}catch(e){uni.showToast({title:e.message||'领取失败',icon:'none'})}finally{this.claiming=false}},async load(){const metas={favorites:{title:'收藏列表',empty:'还没有收藏商品'},following:{title:'关注店铺',empty:'还没有关注店铺'},coupons:{title:'优惠券',empty:'暂无可用优惠券'},posters:{title:'我的海报',empty:'还没有生成商品海报'}};this.meta=metas[this.type]||metas.favorites;this.loading=true;this.error='';try{if(this.type==='favorites')this.items=await api.getFavorites();else if(this.type==='following')this.items=await api.getFollows();else if(this.type==='coupons')this.items=this.couponMode==='public'?await api.getAvailableCoupons():await api.getCoupons();else this.items=await api.getPosters()}catch(e){this.items=[];this.error=e.message||'加载失败'}finally{this.loading=false}},async unfollow(item){try{await api.setFollow(item.id,false);await this.load()}catch(e){uni.showToast({title:e.message||'取消关注失败',icon:'none'})}}}}</script>
<style scoped>.coupon-tabs{display:flex;gap:16rpx;padding:24rpx 28rpx 0}.coupon-tabs button{flex:1;padding:20rpx;border-radius:30rpx;background:var(--surface);color:var(--muted);font-size:26rpx}.coupon-tabs button.active{background:var(--primary);color:#fff}.claim-button{align-self:flex-start;padding:10rpx 26rpx;border-radius:26rpx;background:var(--primary);color:#fff;font-size:23rpx}.claim-button[disabled]{opacity:.5}.coupon-copy .row-title{overflow-wrap:anywhere}.content{padding:24rpx 28rpx}.product-row,.shop-row,.poster-row{display:flex;align-items:center;gap:20rpx;margin-bottom:18rpx;padding:22rpx;border-radius:22rpx;background:var(--surface);color:var(--text);box-shadow:var(--shadow-card)}.product-row image,.poster-row image{width:150rpx;height:150rpx;border-radius:16rpx}.product-row>view,.poster-row>view{min-width:0;flex:1;display:flex;flex-direction:column;gap:12rpx}.product-row .muted,.poster-row .muted{font-size:22rpx}.row-title{font-size:27rpx;font-weight:700}.coupon-card{display:flex;align-items:center;gap:20rpx;margin-bottom:18rpx;padding:28rpx;border-radius:24rpx;background:linear-gradient(120deg,#fff9e9,#ffdfa3);box-shadow:0 12rpx 32rpx rgba(211,145,37,.1)}.coupon-icon{width:76rpx;height:76rpx;display:flex;align-items:center;justify-content:center;border-radius:24rpx;background:rgba(255,255,255,.55)}.coupon-value,.coupon-copy{display:flex;flex-direction:column;gap:8rpx}.coupon-copy{min-width:0;flex:1}.coupon-money{color:var(--primary);font-size:42rpx;font-weight:900}</style>
